func (l *base) detectScanDest() map[string][]string {
	scanDest := map[string][]string{}

	for _, p := range l.osPackages.Packages {
		if p.AffectedProcs == nil {
			continue
		}
		for _, proc := range p.AffectedProcs {
			if proc.ListenPorts == nil {
				continue
			}
			for _, port := range proc.ListenPorts {
				addrs := []string{port.Address}
				if port.Address == "*" {
					addrs = l.ServerInfo.IPv4Addrs
				}
				for _, addr := range addrs {
					scanDest[addr] = append(scanDest[addr], port.Port)
				}
			}
		}
	}

	for addr, ports := range scanDest {
		sort.Strings(ports)
		unique := ports[:0]
		for _, port := range ports {
			if len(unique) == 0 || unique[len(unique)-1] != port {
				unique = append(unique, port)
			}
		}
		scanDest[addr] = unique
	}

	return scanDest
}

